import { z } from 'zod';

// Physics is owned by the runtime, never generated by the model.
export const RESCUE_PHYSICS = {
  width: 960, height: 576, tile: 64, columns: 64, floorY: 448,
  speed: 210, jumpPower: 580, gravity: 1400, playerWidth: 36,
  coyoteMs: 130, bufferMs: 160,
} as const;

const GapSchema = z.object({
  start: z.number().int().min(9).max(54),
  width: z.number().int().min(1).max(2),
  bridge: z.boolean(),
}).strict();

const LevelSchema = z.object({
  title: z.string().min(1).max(24),
  theme: z.enum(['meadow', 'river', 'cave']),
  gaps: z.array(GapSchema).min(1).max(5),
  checkpoints: z.array(z.number().int().min(5).max(56)).min(1).max(3),
  berries: z.array(z.number().int().min(4).max(59)).min(3).max(18),
}).strict();

export const RescueSpecSchema = z.object({
  schemaVersion: z.literal('rescue-1'),
  title: z.string().min(1).max(32),
  doubleJump: z.boolean(),
  friend: z.enum(['rabbit', 'cat']),
  levels: z.array(LevelSchema).length(3),
}).strict();
export type RescueSpec = z.infer<typeof RescueSpecSchema>;
export type RescueLevel = RescueSpec['levels'][number];

export function validateRescueSpec(input: unknown): RescueSpec {
  const spec = RescueSpecSchema.parse(input);
  for (const [index, level] of spec.levels.entries()) {
    const gaps = [...level.gaps].sort((a, b) => a.start - b.start);
    for (const [i, gap] of gaps.entries()) {
      if (i > 0 && gap.start - (gaps[i - 1].start + gaps[i - 1].width) < 6) {
        throw new Error(`第 ${index + 1} 关缺口之间至少留 6 格落脚与助跑空间`);
      }
      const safeRange = RESCUE_PHYSICS.speed * 2 * RESCUE_PHYSICS.jumpPower / RESCUE_PHYSICS.gravity;
      if (gap.width * RESCUE_PHYSICS.tile + 24 > safeRange) {
        throw new Error(`第 ${index + 1} 关存在单次跳跃无法通过的缺口`);
      }
    }
    if (new Set(level.checkpoints).size !== level.checkpoints.length || new Set(level.berries).size !== level.berries.length) {
      throw new Error(`第 ${index + 1} 关检查点或草莓位置重复`);
    }
    for (const point of level.checkpoints) {
      if (gaps.some(gap => point >= gap.start - 1 && point <= gap.start + gap.width)) {
        throw new Error(`第 ${index + 1} 关检查点必须在缺口外的安全地面上`);
      }
    }
  }
  return spec;
}

export const DEFAULT_RESCUE_SPEC: RescueSpec = validateRescueSpec({
  schemaVersion: 'rescue-1', title: '小恐龙救朋友', doubleJump: false, friend: 'rabbit',
  levels: [
    { title: '草莓小径', theme: 'meadow',
      gaps: [{ start: 14, width: 1, bridge: false }, { start: 31, width: 1, bridge: false }, { start: 48, width: 2, bridge: false }],
      checkpoints: [8, 24, 42], berries: [5, 7, 12, 15, 19, 26, 29, 32, 37, 44, 50, 57] },
    { title: '会动的桥', theme: 'river',
      gaps: [{ start: 13, width: 2, bridge: true }, { start: 29, width: 2, bridge: true }, { start: 47, width: 2, bridge: false }],
      checkpoints: [7, 23, 41], berries: [5, 9, 14, 18, 25, 30, 35, 43, 48, 53, 58] },
    { title: '山洞里的朋友', theme: 'cave',
      gaps: [{ start: 12, width: 1, bridge: false }, { start: 26, width: 2, bridge: true }, { start: 39, width: 1, bridge: false }, { start: 53, width: 2, bridge: false }],
      checkpoints: [7, 22, 46], berries: [5, 10, 13, 20, 27, 33, 40, 44, 49, 55, 58] },
  ],
});

export const RESCUE_EXAMPLE_REQUESTS = ['恐龙能跳两次', '加一座会动的桥', '朋友藏在山洞里', '少一点缺口，容易一点', '把朋友换成小猫'];
